'use strict';

// Regression coverage for the "Apply Terra Zone Config Command" Node-RED function node
// generated by migrate-flows-terra-selection-edge.js. P1 (Codex review on PR #191): the node
// used to gate on commandType alone (`if (commandType !== 'UPSERT_ZONE_CONFIG') return [msg,
// null];`), so it intercepted EVERY UPSERT_ZONE_CONFIG delivery -- including ordinary v1
// dashboard edits carrying legacy fields (soilType, notes, timezone, ...) -- and
// osi-zone-commands' validate() then THREW on those legacy payloads because they don't carry
// the Terra-only `terraConfigurationOperation` marker. The function node's own catch swallowed
// that throw into `[null, null]`: no output, no ACK, and the legacy command re-delivers forever.
//
// The fix gates on payload SHAPE (`payload.terraConfigurationOperation === true`) instead of
// command type, before ever calling into osi-zone-commands. This file exercises that gating
// decision directly against the real, shipped function-node source (extracted from flows.json
// and run in a vm sandbox, following the pattern in scripts/verify-strega-gen1.js), with
// osi-zone-commands mocked so each test can assert whether it was invoked at all.

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');
const vm = require('node:vm');

const REPO = path.resolve(__dirname, '..');
const FLOW_PROFILES = [
  'conf/full_raspberrypi_bcm27xx_bcm2712/files/usr/share/flows.json',
  'conf/full_raspberrypi_bcm27xx_bcm2709/files/usr/share/flows.json',
];
const NODE_ID = 'terra-zone-config-command-apply-fn';
const ZONE_UUID = 'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb';
const GATEWAY_EUI = '10AA10AA10AA10AD';

function loadNode(relativeFlowPath) {
  const flows = JSON.parse(fs.readFileSync(path.join(REPO, relativeFlowPath), 'utf8'));
  const node = flows.find((candidate) => candidate.id === NODE_ID);
  assert.ok(node, `missing flow node ${NODE_ID} in ${relativeFlowPath}`);
  assert.equal(typeof node.func, 'string', `${NODE_ID} must include executable source`);
  return node;
}

function runScript(source, sandbox, filename) {
  const script = new vm.Script(source, { filename });
  return script.runInNewContext(sandbox, { timeout: 1000 });
}

function fakeDbHelper() {
  return {
    ok: true,
    value: {
      Database: class {
        close(callback) { callback(); }
      },
    },
  };
}

async function runNode(node, msgPayload, osiLibOverrides) {
  const errors = [];
  const warnings = [];
  const msg = { payload: msgPayload, _commandTypeRecognized: true };
  const sandbox = {
    msg,
    node: {
      error(message) { errors.push(String(message)); },
      warn(message) { warnings.push(String(message)); },
    },
    env: {
      get(name) { return name === 'DEVICE_EUI' ? GATEWAY_EUI : ''; },
    },
    osiLib: {
      require(name) {
        if (Object.prototype.hasOwnProperty.call(osiLibOverrides, name)) return osiLibOverrides[name];
        return { ok: false, error: 'unmocked osi-lib module: ' + name };
      },
    },
  };
  const outcome = runScript(`(() => { ${node.func} })()`, sandbox, `${node.name}.vm.js`);
  const result = outcome && typeof outcome.then === 'function' ? await outcome : outcome;
  // `result` is a foreign-realm array (its own vm.Script literal), so it structurally matches but
  // is never reference-equal to a same-shaped array built in this realm -- assert.deepEqual (even
  // non-strict) from node:assert/strict rejects that as "same structure but not reference-equal".
  // Callers must compare result.length/result[0]/result[1] individually instead of deep-equaling
  // the whole array; `msg` itself is returned so pass-through can be checked by reference.
  assert.ok(Array.isArray(result), `${node.name} must return a Node-RED output array`);
  assert.equal(result.length, 2, `${node.name} must return a 2-output array (outputs: 2)`);
  return { result, errors, warnings, msg };
}

for (const relativeFlowPath of FLOW_PROFILES) {
  test(`${relativeFlowPath}: passes a legacy (non-Terra) UPSERT_ZONE_CONFIG payload through unhandled`, async () => {
    const node = loadNode(relativeFlowPath);
    let applyCalled = false;
    const legacyPayload = {
      _pendingCommandEnvelope: {
        commandId: 9101,
        commandType: 'UPSERT_ZONE_CONFIG',
        effectKey: null,
        payload: {
          // A real v1 dashboard zone-config edit: no terraConfigurationOperation marker, and it
          // carries legacy fields osi-zone-commands' validate() has never known about.
          zoneUuid: ZONE_UUID,
          gatewayDeviceEui: GATEWAY_EUI,
          soilType: 'loam',
          notes: 'operator note from the v1 dashboard',
          timezone: 'Europe/Zurich',
        },
      },
    };
    const { result, errors, warnings, msg } = await runNode(node, legacyPayload, {
      'osi-db-helper': fakeDbHelper(),
      'zone-commands': {
        ok: true,
        value: { applyZoneCommand: async () => { applyCalled = true; return { handled: true, ack: {} }; } },
      },
    });

    // Passed through on output 1 (to the legacy Route Command path), nothing on output 2 (no
    // Terra ACK), and the library was never even called with this payload.
    assert.equal(result[0], msg, 'unhandled legacy commands must pass the original msg through unchanged');
    assert.equal(result[0].payload, legacyPayload);
    assert.equal(result[1], null, 'a pass-through must not also emit a Terra ACK');
    assert.equal(applyCalled, false, 'legacy payload must never reach applyZoneCommand');
    assert.deepEqual(errors, [], 'legacy payload must not be logged as a Terra command error');
    assert.deepEqual(warnings, []);
  });

  test(`${relativeFlowPath}: still routes a genuine Terra payload (marker true) into applyZoneCommand`, async () => {
    const node = loadNode(relativeFlowPath);
    let seenEnvelope = null;
    const terraPayload = {
      _pendingCommandEnvelope: {
        commandId: 9102,
        commandType: 'UPSERT_ZONE_CONFIG',
        effectKey: null,
        payload: {
          zoneUuid: ZONE_UUID,
          gatewayDeviceEui: GATEWAY_EUI,
          cropType: 'maize',
          terraConfigurationOperation: true,
        },
      },
    };
    const { result, errors } = await runNode(node, terraPayload, {
      'osi-db-helper': fakeDbHelper(),
      'zone-commands': {
        ok: true,
        value: {
          applyZoneCommand: async (db, envelope) => {
            seenEnvelope = envelope;
            return {
              handled: true,
              ack: { commandId: envelope.commandId, result: 'APPLIED' },
            };
          },
        },
      },
    });

    assert.ok(seenEnvelope, 'Terra-marked payload must reach applyZoneCommand');
    assert.equal(seenEnvelope.payload.terraConfigurationOperation, true);
    assert.equal(result[0], null, 'a handled Terra command must not fall through to the legacy router');
    assert.ok(result[1] && typeof result[1].topic === 'string' && result[1].topic.startsWith('devices/'));
    assert.deepEqual(JSON.parse(result[1].payload), { commandId: 9102, result: 'APPLIED' });
    assert.deepEqual(errors, []);
  });

  test(`${relativeFlowPath}: fails closed with no ACK when a marker-true Terra payload is rejected as malformed`, async () => {
    const node = loadNode(relativeFlowPath);
    const malformedTerraPayload = {
      _pendingCommandEnvelope: {
        commandId: 9103,
        commandType: 'UPSERT_ZONE_CONFIG',
        effectKey: null,
        payload: {
          terraConfigurationOperation: true,
          // Stands in for a real validate() throw (e.g. missing/garbled required fields); the
          // node's own try/catch is what's under test here, not osi-zone-commands' validation.
        },
      },
    };
    const { result, errors } = await runNode(node, malformedTerraPayload, {
      'osi-db-helper': fakeDbHelper(),
      'zone-commands': {
        ok: true,
        value: {
          applyZoneCommand: async () => {
            const error = new Error('payload shape mismatch; missing=zoneUuid,gatewayDeviceEui,...');
            error.code = 'malformed_command';
            throw error;
          },
        },
      },
    });

    assert.equal(result[0], null, 'malformed Terra payload must not pass through to the legacy router');
    assert.equal(result[1], null, 'malformed Terra payload must not ACK');
    assert.equal(errors.length, 1);
    assert.match(errors[0], /Terra zone-config command apply failed closed/);
    assert.match(errors[0], /payload shape mismatch/);
  });
}
